head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "3";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp;
scwin.vSelObj;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        lbl_ReturnPos.hide();
        grd_Grid_excel.hide();
        showload.style.display = "none";

        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_List);
        $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
        $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
        $c.bns.BnsPanelToGroupBox(pnl_RelInst);
        $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);

        // 접수 임시데이터셋설정

        // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

        // 시장조치구분 설정
        scwin.setMktactCd();
        // 콤보설정
        scwin.setComboCode();
        // 목록조회
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_excel_OnLoadCompleted
 * @description dts_List_excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_excel_OnLoadCompleted = function(rowcount) {
    try {
        showload.style.display = "none";
        $c.data.downloadGridViewExcel(grd_Grid_excel, {fileName: "일괄상장 연간등록 목록", type: "8"});

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 복구
        btn_Excel.setDisabled(false);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05200.dts_List_excel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.vRowCount = row;
            scwin.vBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
            const mktCd = dts_List.getCellData(row, "BND_MKTACT_TP_CD");
            // 지방채
            cmb_MunibndTpCd.setDisabled(true);
            if (mktCd === '122') {
                cmb_MunibndTpCd.setDisabled(false);
            }

            // 채권유형 국채
            if (mktCd === '112') {
                cmb_BndTpCd.setValue('GB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 지방채
            else if (mktCd === '122') {
                cmb_BndTpCd.setValue('MB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 특수채
            else if (mktCd === '132') {
                cmb_BndTpCd.setValue('AB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 지방공사채
            else if (mktCd === '142') {
                cmb_BndTpCd.setValue('CO');
                cmb_BndTpCd.setDisabled(true);
            } else {
                cmb_BndTpCd.setDisabled(false);
            }
            scwin.dtlSync();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05200.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05200.dts_List_OnLoadError" });
    }
};

