/**
 * @method
 * @name dts_Credit_OnLoadCompleted
 * @description dts_Credit 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Credit_OnLoadCompleted = function(rowcount) {
    try {
        cmb_CreditValuInstCd1.setValue('0');
        cmb_ByinstCreditValuGrd1.setValue('0');
        cmb_SfValuYn1.setValue('');
        cmb_CreditValuInstCd2.setValue('0');
        cmb_ByinstCreditValuGrd2.setValue('0');
        cmb_SfValuYn2.setValue('');
        cmb_CreditValuInstCd3.setValue('0');
        cmb_ByinstCreditValuGrd3.setValue('0');
        cmb_SfValuYn3.setValue('');
        cmb_CreditValuInstCd4.setValue('0');
        cmb_ByinstCreditValuGrd4.setValue('0');
        cmb_SfValuYn4.setValue('');
        if (rowcount > 0) {
            for (let idx = 1; idx <= rowcount; idx++) {
                if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') === '9201') {
                    cmb_CreditValuInstCd1.setValue(dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                    cmb_ByinstCreditValuGrd1.setValue(dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                    cmb_SfValuYn1.setValue(dts_Credit.getCellData(idx, "SF_VALU_YN"));
                } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') === '9202') {
                    cmb_CreditValuInstCd2.setValue(dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                    cmb_ByinstCreditValuGrd2.setValue(dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                    cmb_SfValuYn2.setValue(dts_Credit.getCellData(idx, "SF_VALU_YN"));
                } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') === '9203') {
                    cmb_CreditValuInstCd3.setValue(dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                    cmb_ByinstCreditValuGrd3.setValue(dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                    cmb_SfValuYn3.setValue(dts_Credit.getCellData(idx, "SF_VALU_YN"));
                } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') === '9204') {
                    cmb_CreditValuInstCd4.setValue(dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                    cmb_ByinstCreditValuGrd4.setValue(dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                    cmb_SfValuYn4.setValue(dts_Credit.getCellData(idx, "SF_VALU_YN"));
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05200.dts_Credit_OnLoadCompleted" });
    }
};

