///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 신청/접수 목록을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; // 시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; // 채권처리구분(1:신청,2:접수)

    let dsNm = 'BNS_APPL_ACPT_LIST';
    let qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    $c.bns.fn_SearchBns("ULDBNS05200.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name acpt
 * @description 일괄상장 연간 접수 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function() {
    // 종목정보체크
    if (await scwin.checkEach() > 0) return;
    const hasAttachDoc = dts_List.getCellData(1, "HAS_ATTACH_DOC");
    if (scwin.processGp === '1') {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '접수')) return;
    } else {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '수정')) return;
    }

    // 발행방법설정
    const ISU_METHD_INDIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_INDIRECT');
    const ISU_METHD_DIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_DIRECT');
    const ISU_METHD_PPBOND = dts_IsuInfo.getCellData(1, 'ISU_METHD_PPBOND');
    dts_IsuInfo.setCellData(1, 'BND_ISU_METHD_CD', ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND);

    // 탭 데이터셋 설정
    scwin.setCreditData();

    // 변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    let url = "/bns/PackList.do?method=processAcptByyy";
    if (scwin.processGp === '2') {
        url = "/bns/PackList.do?method=updateAcptByyy";
    }
    url += "&SCREN_ID=" + "ULDBNS05200.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    let dsKeyValue = "JSP(";
    dsKeyValue += "I:pInput=dts_IsuInfo";
    dsKeyValue += ", I:pInput1=dts_Credit";
    dsKeyValue += ", I:pInput8=dts_SplitRedmpt";
    dsKeyValue += ")";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = dsKeyValue;
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name setMktactCd
 * @description 신규상장 채권시장조치구분코드를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setMktactCd = function() {
    scwin.vMktactCd = "112122132";
};

/**
 * @method
 * @name dtlSync
 * @description 그리드 선택 시 상세내역을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.dtlSync = function() {
    let param = '';
    param += '&{P}V_BND_APPL_ID=' + scwin.vBndApplId; // 채권신청ID
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd; // 채권처리구분(1:신청,2:접수)

    // 종목정보
    let dsNm = 'BNS_ISU_INFO';
    let qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    $c.bns.fn_SearchBns("ULDBNS05200.xml", dts_IsuInfo, dsNm, qryId, param);

    // 신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listCredit';
    $c.bns.fn_SearchBns("ULDBNS05200.xml", dts_Credit, dsNm, qryId, param);

    // 분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns("ULDBNS05200.xml", dts_SplitRedmpt, dsNm, qryId, param);
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터를 정의한다.
