/**
 * @method
 * @name minusGumriOK
 * @description 개별 체크한다. (JACKAL_191129)
 * @param {Object} obj 컴포넌트
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.minusGumriOK = function(obj, msg) {
    const obj_rt = obj.getValue();
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            // setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};

/**
 * @method
 * @name minusGumriCheck
 * @description 개별 체크한다. (JACKAL_191129 / edt_CoupnRt COUPN_RT / edt_ScbdInt SCBD_INT / edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT / edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT / edt_GrtYd GRT_YD / edt_AddYd ADD_YD)
 * @returns {void}
 * @hidden N
 */
scwin.minusGumriCheck = function() {
    if (!scwin.minusGumriOK(edt_CoupnRt, '표면이자율') &&
        !scwin.minusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !scwin.minusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !scwin.minusGumriOK(edt_GrtYd, '보장수익률') &&
        !scwin.minusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};

/**
 * @method
 * @name checkEach
 * @description 개별정보를 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkEach = async function() {
    // 마이너스 금리 체크
    if (!scwin.minusGumriCheck()) return 1; // JACKAL_191129

    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") === '') {
        await $c.win.alert("채권유형을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") === "MB" && dts_IsuInfo.getCellData(1, "MUNIBND_TP_CD") === '') {
        await $c.win.alert("지방채구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "NUSUAL_BND_TP_CD") === '') {
        await $c.win.alert("특이채권유형을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "INT_PAY_METHD_CD") === '') {
        await $c.win.alert("이자지급방법을 선택하십시오.");
        return 1;
    }
    /* 확인 */
    if (dts_IsuInfo.getCellData(1, "ISU_METHD_INDIRECT") !== '1' &&
        dts_IsuInfo.getCellData(1, "ISU_METHD_DIRECT") !== '1' &&
        dts_IsuInfo.getCellData(1, "ISU_METHD_PPBOND") !== '1') {
        // 2006.11.23 add
        await $c.win.alert("발행방법을 선택하십시오.");
        return 1;
    }

    // 표면이자율확정
    if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === '') {
        await $c.win.alert("표면이자율 확정여부를 선택하십시오.");
        return 1;
    } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === 'Y' &&
        dts_IsuInfo.getCellData(1, "COUPN_RT") === '') {
        await $c.win.alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
        return 1;
    } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === 'N' &&
        dts_IsuInfo.getCellData(1, "COUPN_RT") !== '') {
        if (!window.confirm('표면이자율이 미확정입니다.\n그래도 처리하시겠습니까?')) return 1;
    }

    // 류인욱팀장님요구로 사모채도 상장(2006.1130)
    // 특수채일경우만 사모가 상장될수가 있고 회사채인경우는 공모로 상장됨
    let msg = '';
    if (dts_IsuInfo.getCellData(1, "ISU_METHD_PPBOND") === '1' &&
        dts_IsuInfo.getCellData(1, "BND_TP_CD") !== "AB") {
        // 2006.11.23 add
        msg = "" + "발행방법이 사모채로 입력되어있습니다. " + "\n" + "\n사모채는 채권유형이 특수채일때만 입력가능한 항목입니다." + "\n그래도 작업을 계속하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }
    if (dts_IsuInfo.getCellData(1, "BND_INT_PAY_DD_BAS_TP_CD") === '') {
        await $c.win.alert("이자일지급기준구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "INT_MMEND_TP_CD") === '') {
        await $c.win.alert("이자월말구분을 선택하십시오.");
        return 1;
    }
    if (dts_IsuInfo.getCellData(1, "REDMPT_METHD_TP_CD") !== '2' &&
        dts_IsuInfo.getCellData(1, "SPLIT_REDMPT_TP_CD") !== '') {
        await $c.win.alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if (edt_GrtYd.getValue() !== '') {
        if (edt_GrtYd.getValue() >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
        if (edt_ExpRedmptRto.getValue() === '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
    }

    // 특수채체크
    if (cmb_BndTpCd.getValue() === 'AB') {
        if (dts_IsuInfo.getCellData(1, 'SPECLBND_ISUR_CD') === '') {
            await $c.win.alert('특수채 발행기관 코드가 없습니다.');
            return 1;
        }
    } else {
        dts_IsuInfo.setCellData(1, 'SPECLBND_ISUR_CD', '');
    }

    // 분할상환체크
    const rowCnt = dts_SplitRedmpt.getRowCount();
    for (let idx = 1; idx <= rowCnt; idx++) {
        if (dts_SplitRedmpt.getCellData(idx, 'INT_PAY_DD').length !== 8) {
            await $c.win.alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
            dts_SplitRedmpt.setRowPosition(idx, 0);
            return 1;
        }
    }

    // 보장수익률체크
    if (edt_GrtYd.getValue() !== '' &&
        edt_GrtYdStrtDd.getValue() === '') {
        await $c.win.alert('보장수익률 적용일을 입력하셔야 합니다.');
        return 1;
    }

    // 추가수익률체크
    if (edt_AddYd.getValue() !== '' &&
        edt_AddYdStrtDd.getValue() === '') {
        await $c.win.alert('추가수익률 적용일을 입력하셔야 합니다.');
        return 1;
    }
    if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
    return 0;
};

